#!/usr/bin/env bash
# Question 7: New Pods rejected in ${Q7_NS}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q7_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q7_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q7_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q7_APP}
  namespace: ${Q7_NS}
  labels: { app: ${Q7_APP} }
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q7_APP} }
  template:
    metadata:
      labels: { app: ${Q7_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 100m, memory: 64Mi }
EOF

case "${Q7_FAULT}" in
  quota-pods)
    kubectl -n "${Q7_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"ResourceQuota","metadata":{"name":"tenant-quota"},"spec":{"hard":{"pods":"1"}}}'
    ;;
  quota-limits)
    kubectl -n "${Q7_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"ResourceQuota","metadata":{"name":"compute-quota"},"spec":{"hard":{"requests.cpu":"2","limits.cpu":"4"}}}'
    ;;
  limitrange-max)
    kubectl -n "${Q7_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"LimitRange","metadata":{"name":"container-limits"},"spec":{"limits":[{"type":"Container","max":{"cpu":"50m"}}]}}'
    ;;
  limitrange-min)
    kubectl -n "${Q7_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"LimitRange","metadata":{"name":"container-floor"},"spec":{"limits":[{"type":"Container","min":{"memory":"128Mi"}}]}}'
    ;;
  pod-security)
    kubectl label namespace "${Q7_NS}" pod-security.kubernetes.io/enforce=restricted --overwrite
    ;;
  webhook)
    kubectl label namespace "${Q7_NS}" policy.cka.lab/checked=true --overwrite
    kubectl apply -f - <<< '{"apiVersion":"admissionregistration.k8s.io/v1","kind":"ValidatingWebhookConfiguration","metadata":{"name":"'"${Q7_NS}"'-pod-policy"},"webhooks":[{"name":"pods.policy.cka.lab","failurePolicy":"Fail","sideEffects":"None","timeoutSeconds":3,"admissionReviewVersions":["v1"],"clientConfig":{"service":{"name":"pod-policy","namespace":"'"${Q7_NS}"'","path":"/validate"},"caBundle":"LS0tLS0tRU5EIENFUlRJRklDQVRFLS0tLS0t"},"rules":[{"apiGroups":[""],"apiVersions":["v1"],"operations":["CREATE"],"resources":["pods"],"scope":"Namespaced"}],"namespaceSelector":{"matchLabels":{"policy.cka.lab/checked":"true"}}}]}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q7_NS}" scale "deployment/${Q7_APP}" --replicas=2
# What "do not change the Deployment" means: this object, replica count and Pod spec. A rollout
# restart only annotates the template, so it stays allowed.
kubectl -n "${Q7_NS}" get deployment "${Q7_APP}" -o jsonpath='{.metadata.uid} {.spec.replicas} {.spec.template.spec}' > "/var/tmp/cka-q7.deploy"
chmod 644 "/var/tmp/cka-q7.deploy"
sleep 15
[[ "$(kubectl -n "${Q7_NS}" get deployment "${Q7_APP}" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "${Q7_APP} still runs 2 replicas" >&2; exit 1; }
